import java.io.*;
import java.util.*;

public class Main {
    static final int MAXN = 5007;
    static final long INF = Long.MAX_VALUE / 4;
    static final long MOD = 1000000007L;

    static class Edge {
        int from, to;
        long cap, cost, flow;
        Edge(int a, int b, long c, long d) {
            from = a;
            to = b;
            cap = c;
            cost = d;
            flow = 0;
        }
    }

    static List<Edge> edges = new ArrayList<>();
    static List<Integer>[] adj = new ArrayList[MAXN];
    static long[] dist = new long[MAXN];
    static long[] potential = new long[MAXN];
    static int[] parent = new int[MAXN];

    static void addEdge(int u, int v, long cap, long cost) {
        adj[u].add(edges.size());
        edges.add(new Edge(u, v, cap, cost));
        adj[v].add(edges.size());
        edges.add(new Edge(v, u, 0, -cost));
    }

    static void fordBellman(int s, int n) {
        Arrays.fill(potential, INF);
        potential[s] = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < edges.size(); j++) {
                Edge e = edges.get(j);
                if (e.cap == e.flow) continue;
                if (potential[e.from] == INF) continue;
                if (potential[e.to] > potential[e.from] + e.cost) {
                    potential[e.to] = potential[e.from] + e.cost;
                }
            }
        }
    }

    static void dijkstra(int s) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingLong(p -> p.dist));
        pq.add(new Pair(0, s));
        while (!pq.isEmpty()) {
            Pair cur = pq.poll();
            int v = cur.node;
            if (cur.dist != dist[v]) continue;
            for (int eid : adj[v]) {
                Edge e = edges.get(eid);
                if (e.cap == e.flow) continue;
                int to = e.to;
                long len = e.cost + potential[v] - potential[to];
                if (dist[v] + len < dist[to]) {
                    dist[to] = dist[v] + len;
                    parent[to] = eid;
                    pq.add(new Pair(dist[to], to));
                }
            }
        }
    }

    static long[] mincostMaxflow(int s, int t) {
        fordBellman(s, 50);
        dijkstra(s);
        long flow = 0, cost = 0;
        while (true) {
            if (dist[t] == INF) break;
            long pushed = INF;
            long sum = 0;
            for (int v = t; v != s; v = edges.get(parent[v]).from) {
                int eid = parent[v];
                pushed = Math.min(pushed, edges.get(eid).cap - edges.get(eid).flow);
                sum += edges.get(eid).cost;
            }
            flow += pushed;
            cost += pushed * sum;
            for (int v = t; v != s; v = edges.get(parent[v]).from) {
                int eid = parent[v];
                edges.get(eid).flow += pushed;
                edges.get(eid ^ 1).flow -= pushed;
            }
            dijkstra(s);
            System.arraycopy(dist, 0, potential, 0, MAXN);
        }
        return new long[]{cost, flow};
    }

    static void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int[] cnt = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(st.nextToken()) - 1;
            cnt[x]++;
        }

        // Initialize adjacency
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }

        // Edges from source 5000 to buildings
        for (int i = 0; i < n; i++) {
            addEdge(5000, i, cnt[i], 0);
        }

        // Read roads and add layered edges
        for (int t = 0; t < m; t++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int i = 0; i < 99; i++) {
                long cur = d;
                for (int j = 0; j < 50; j++) {
                    addEdge(u + i * 50, v + (i + 1) * 50, 1, cur);
                    addEdge(v + i * 50, u + (i + 1) * 50, 1, cur);
                    cur += 2 * d;
                }
            }
        }

        // Edges from special node 0 layer to sink 5001
        for (int i = 0; i <= 99; i++) {
            addEdge(0 + i * 50, 5001, INF, (long) c * i);
        }

        // Edges connecting same building across layers
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 99; j++) {
                addEdge(i + j * 50, i + (j + 1) * 50, INF, 0);
            }
        }

        long[] res = mincostMaxflow(5000, 5001);
        // assert res[1] == k; // optional check
        System.out.println(res[0]);
    }

    public static void main(String[] args) throws IOException {
        solve();
    }

    static class Pair {
        long dist;
        int node;
        Pair(long d, int n) {
            dist = d;
            node = n;
        }
    }
}
